    left: 50%;
    top: 50%;
    z-index: 99;
    margin: -75px 0 0 -75px;
    border: 16px solid #f3f3f3;
    border-radius: 50%;
    border-top: 16px solid #3498db;
    width: 120px;
    height: 120px;
    -webkit-animation: mod_pdfannotator_spin 2s linear infinite; /* Open LMS patch for INT-21588 */
    animation: mod_pdfannotator_spin 2s linear infinite; /* Open LMS patch for INT-21588 */
}

@-webkit-keyframes mod_pdfannotator_spin { /* Open LMS patch for INT-21588 */
    0% {
        -webkit-transform: rotate(0deg);
    }
    100% {
        -webkit-transform: rotate(360deg);
    }
}

@keyframes mod_pdfannotator_spin { /* Open LMS patch for INT-21588 */
    0% {
        transform: rotate(0deg);
    }
    100% {
        transform: rotate(360deg);
    }
}

/* Add animation to "page content" */
.path-mod-pdfannotator .animate-bottom {
    position: relative;
    -webkit-animation-name: mod_pdfannotator_animatebottom; /* Open LMS patch for INT-21588 */
    -webkit-animation-duration: 1s;
    animation-name: mod_pdfannotator_animatebottom; /* Open LMS patch for INT-21588 */
    animation-duration: 1s;
}

@-webkit-keyframes mod_pdfannotator_animatebottom { /* Open LMS patch for INT-21588 */
    from {
        bottom: -100px;
        opacity: 0;
    }
    to {
        bottom: 0;
        opacity: 1;
    }
}

@keyframes mod_pdfannotator_animatebottom { /* Open LMS patch for INT-21588 */
