.path-mod-questionnaire .slidecontainer {
    width: 100%;
}

.path-mod-questionnaire .slider {
    -webkit-appearance: none;
    width: 100%;
    outline: none;
    opacity: 0.7;
    -webkit-transition: .2s;
    transition: opacity .2s;
    float: left;
    margin-top: 40px;
}
.path-mod-questionnaire .slider input {
    width: 100%;
}

.path-mod-questionnaire .slider:hover {
    opacity: 1;
}

.path-mod-questionnaire .slider::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    width: 100%;
    height: 25px;
    background: #04aa6d;
    cursor: pointer;
    border-radius: 50%;
}

.path-mod-questionnaire .slider::-moz-range-thumb {
    width: 25px;
    height: 25px;
    background: #04aa6d;
    cursor: pointer;
}

.path-mod-questionnaire .question-slider {
    display: flex;
    align-items: baseline;
}

.path-mod-questionnaire .left-side-label {
    text-align: right;
    padding-right: 20px;
    margin-top: 40px;
    flex-grow: 1;
}

.path-mod-questionnaire .right-side-label {
    text-align: left;
    padding-left: 20px;
    margin-top: 40px;
    flex-grow: 1;
}

.path-mod-questionnaire .middle-side-content {
    flex-grow: 8;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
}

.path-mod-questionnaire .middle-side-label {
    text-align: center;
}

.path-mod-questionnaire .bubble {
    background: #000;
    color: white;
    padding: 3px;
    border-radius: 10px;
    left: 50%;
    transform: translate(-52%, -50px);
    position: relative;
    text-align: center;
    width: 40px;
}
.path-mod-questionnaire .bubble::after {
    content: "";
    position: absolute;
    width: 2px;
    height: 2px;
    left: 50%;
}

/* Styles for the print blank page. */
