    -webkit-appearance: none;
    appearance: none;
    width: 0;
    height: 0;
}

#page-mod-questionnaire-print input[type="range"]::-moz-range-thumb {
    -webkit-appearance: none;
    appearance: none;
    width: 0;
    height: 0;
}

#page-mod-questionnaire-print input[type="range"]::-ms-thumb {
    -webkit-appearance: none;
    appearance: none;
    width: 0;
    height: 0;
}

