/** VARIABLES BXSLIDER
===================================*/
/** RESET AND LAYOUT
===================================*/
.bx-wrapper {
    position: relative;
    margin-bottom: 0;
    padding: 0;
    *zoom: 1;
    -ms-touch-action: pan-y;
    touch-action: pan-y;
    z-index: 1;
}
.bx-wrapper img {
    max-width: 100%;
    display: block;
}
.bxslider {
    margin: 0;
    padding: 0;
}
ul.bxslider {
    list-style: none;
}
.bx-viewport {
    /*fix other elements on the page moving (on Chrome)*/
    -webkit-transform: translatez(0);
    z-index: 1;
}
.block.block_products_catalog .featuredproducts-box .bx-viewport {
    max-height: 405px;
}
.block.block_products_catalog .featuredproducts-box .image-overlay {
    display:block;
    width: 100%;
    height: 100%;
    position: absolute;
    top: 0;
    left: 0;
    background-color: rgba(32, 39, 50, 0.3);
}
.block.block_products_catalog .featuredproducts-box .product-add-button .add-product-button {
    float: left;
    margin: 0 .3rem .3rem;
}
.block.block_products_catalog .featuredproducts-box .buyseats-button-block {
    float: right;
    margin: 0 .3rem .3rem;
    z-index: 2;
}
.block.block_products_catalog .featuredproducts-box .product-add-button .btn-primary-inverse {
    color: #175B96;
}
.block.block_products_catalog .featuredproducts-box .product-add-button .buyseats-button-block .btn.btn-primary {
    border-radius: 0 3px 3px 0;
}
.block.block_products_catalog .product-sessions.intellicart-filter-form.product-info-item {
