}
.block.block_products_catalog .date-range-input {
    margin-right: .5rem;
    position: relative;
}
.block.block_products_catalog .product-details .date-range-input {
    width: 220px;
}
.block.block_products_catalog .date-range-input input[type="text"] {
    padding-right: 2rem;
}
.block.block_products_catalog .date-range-input i {
    position: absolute;
    right: .8rem;
    top: 50%;
    font-size: .9rem;
    margin-top: -.5rem;
    color: #9198a8;
}

