/* =============================================================================
 * FullCalendar — additive fixes for #ic_calendar (My Calendar) and #ic_mysessions (My Sessions).
 * Scoped to those roots so catalog / product cards are unaffected.
 * ============================================================================= */

#ic_calendar .fc-time-grid .fc-event-container,
#ic_mysessions .fc-time-grid .fc-event-container {
    height: auto !important;
    min-height: 0;
}

/* intellicart .sessions-list .fc-event { position:relative } overrides FC absolute; cumulative slot drift */
#ic_calendar .fc-time-grid .fc-event.fc-time-grid-event,
#ic_mysessions .fc-time-grid .fc-event.fc-time-grid-event {
    position: absolute !important;
}

/* intellicart axis labels: absolute + translateY misalign from slat grid */
#ic_calendar.fc-ltr .fc-time-grid .fc-slats .fc-axis span,
#ic_mysessions.fc-ltr .fc-time-grid .fc-slats .fc-axis span,
#ic_calendar .fc-ltr .fc-time-grid .fc-slats .fc-axis span,
#ic_mysessions .fc-ltr .fc-time-grid .fc-slats .fc-axis span {
    position: static;
    left: auto;
    transform: none;
}
#ic_calendar .fc-time-grid tr[data-time="00:00:00"] .fc-axis span,
#ic_mysessions .fc-time-grid tr[data-time="00:00:00"] .fc-axis span {
    transform: none;
}

#ic_calendar .fc-agendaWeek-view .fc-time-grid-event.fc-short .fc-time span,
#ic_calendar .fc-agendaDay-view .fc-time-grid-event.fc-short .fc-time span,
#ic_mysessions .fc-agendaWeek-view .fc-time-grid-event.fc-short .fc-time span,
#ic_mysessions .fc-agendaDay-view .fc-time-grid-event.fc-short .fc-time span {
    display: none !important;
}

#ic_calendar .fc-time-grid-event .ic-calendar-course-line--agenda,
#ic_mysessions .fc-time-grid-event .ic-calendar-course-line--agenda {
    font-size: 9px;
    line-height: 1.25;
    margin-top: 3px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

#ic_calendar .fc-time-grid-event .ic-calendar-course-line--agenda .course-link,
#ic_mysessions .fc-time-grid-event .ic-calendar-course-line--agenda .course-link {
    color: #3a87ad;
    font-weight: 600;
}

/* Week / day: inner padding + clock icon on time (match intellicart .fc-agendaWeek-view rules) */
#ic_calendar .fc-agendaWeek-view .fc-time-grid-event .fc-content,
#ic_calendar .fc-agendaDay-view .fc-time-grid-event .fc-content,
#ic_mysessions .fc-agendaWeek-view .fc-time-grid-event .fc-content,
#ic_mysessions .fc-agendaDay-view .fc-time-grid-event .fc-content {
    padding: 8px 8px 8px 10px !important;
    box-sizing: border-box;
}

#ic_calendar .fc-agendaWeek-view .fc-time-grid-event .fc-time span,
#ic_calendar .fc-agendaDay-view .fc-time-grid-event .fc-time span,
#ic_mysessions .fc-agendaWeek-view .fc-time-grid-event .fc-time span,
#ic_mysessions .fc-agendaDay-view .fc-time-grid-event .fc-time span {
    padding-left: 17px !important;
    position: relative !important;
}

#ic_calendar .fc-agendaWeek-view .fc-time-grid-event .fc-time span::before,
#ic_calendar .fc-agendaDay-view .fc-time-grid-event .fc-time span::before,
#ic_mysessions .fc-agendaWeek-view .fc-time-grid-event .fc-time span::before,
#ic_mysessions .fc-agendaDay-view .fc-time-grid-event .fc-time span::before {
    content: "\e94f";
    font-family: "icons-font" !important;
    font-style: normal;
    font-weight: normal;
    color: #3a87ad;
    font-variant: normal;
    text-transform: none;
    line-height: 1;
    position: absolute;
    left: 0;
    top: 50%;
    transform: translateY(-50%);
}

/* Month (day grid): same chip look as week — light fill, dark text, course line first */
#ic_calendar .fc-month-view .fc-day-grid-event,
#ic_mysessions .fc-month-view .fc-day-grid-event {
    background-color: rgba(58, 135, 173, 0.1) !important;
    border: none !important;
    border-left: 3px solid #3a87ad !important;
    color: #333 !important;
    padding-left: 0 !important;
    margin: 2px 2px 1px 2px !important;
}

#ic_calendar .fc-month-view .fc-day-grid-event::before,
#ic_mysessions .fc-month-view .fc-day-grid-event::before {
    display: none !important;
    content: none !important;
}

#ic_calendar .fc-month-view .fc-day-grid-event .fc-content,
#ic_mysessions .fc-month-view .fc-day-grid-event .fc-content {
    display: flex !important;
    flex-direction: column !important;
    align-items: flex-start !important;
    white-space: normal !important;
    overflow: visible !important;
    padding: 6px 8px 6px 10px !important;
    box-sizing: border-box;
}

/* Same stack as week (after column-reverse): course → session title → time + clock */
#ic_calendar .fc-month-view .fc-day-grid-event .ic-calendar-course-line--month,
#ic_mysessions .fc-month-view .fc-day-grid-event .ic-calendar-course-line--month {
    order: 1;
}

#ic_calendar .fc-month-view .fc-day-grid-event .fc-title,
#ic_mysessions .fc-month-view .fc-day-grid-event .fc-title {
    order: 2;
}

#ic_calendar .fc-month-view .fc-day-grid-event .fc-time,
#ic_mysessions .fc-month-view .fc-day-grid-event .fc-time {
    order: 3;
}

#ic_calendar .fc-month-view .ic-calendar-course-line--month,
#ic_mysessions .fc-month-view .ic-calendar-course-line--month {
    font-size: 9px;
    line-height: 1.25;
    width: 100%;
    margin-bottom: 4px;
}

#ic_calendar .fc-month-view .ic-calendar-course-line--month .course-link,
#ic_mysessions .fc-month-view .ic-calendar-course-line--month .course-link {
    color: #3a87ad;
    font-weight: 600;
}

#ic_calendar .fc-month-view .fc-day-grid-event .fc-time,
#ic_mysessions .fc-month-view .fc-day-grid-event .fc-time {
    display: block !important;
    font-size: 9px !important;
    color: #3a87ad !important;
    font-weight: 600 !important;
    margin: 4px 0 0 0 !important;
    position: relative !important;
    padding-left: 17px !important;
    align-self: flex-start;
}

#ic_calendar .fc-month-view .fc-day-grid-event .fc-time span,
#ic_mysessions .fc-month-view .fc-day-grid-event .fc-time span {
    padding-left: 0 !important;
    position: static !important;
}

#ic_calendar .fc-month-view .fc-day-grid-event .fc-time::before,
#ic_mysessions .fc-month-view .fc-day-grid-event .fc-time::before {
    content: "\e94f";
    font-family: "icons-font" !important;
    font-style: normal;
    font-weight: normal;
    color: #3a87ad;
    font-variant: normal;
    text-transform: none;
    line-height: 1;
    position: absolute;
    left: 0;
    top: 50%;
    transform: translateY(-50%);
}

#ic_calendar .fc-month-view .fc-day-grid-event .fc-title,
#ic_mysessions .fc-month-view .fc-day-grid-event .fc-title {
    font-size: 11px !important;
    font-weight: 700 !important;
    color: #000 !important;
    white-space: normal !important;
    line-height: 1.2 !important;
    margin: 0 !important;
}

.fc-agendaDay-view .fc-v-event.fc-event.fc-start.fc-end.event-default::before {
    content: none;
}
.fc-agendaDay-view .fc-v-event.fc-event.fc-start.fc-end.event-default .fc-content .fc-time span {
    color: #3a87ad;
}
.fc-agendaDay-view .fc-v-event.fc-event.fc-start.fc-end.event-default .fc-content .fc-time span:before {
    content: "\e94f";
    font-family: "icons-font" !important;
    font-style: normal;
    font-weight: 400;
    color: #3a87ad;
    font-variant: normal;
    text-transform: none;
    line-height: 1;
    position: absolute;
    left: 0;
    top: 50%;
    transform: translateY(-50%);
}

.fc-agendaDay-view .fc-content-col .fc-event-container .fc-time-grid-event .fc-title {
    color: black;
}
.fc-agendaDay-view .fc-content-col .fc-event-container .fc-time-grid-event .fc-time {
    color: #3a87ad;
    padding-left: 0px;
}
#ic_calendar .fc-time-grid .fc-event.fc-time-grid-event {
    overflow: auto;
}
.block_recent_activity .unlist li {
    margin-bottom: 1em;
}

.block_recent_activity li .head .date {
    float: right;
}

.block_report_graph .rb-block-svggraph {
    text-align: center;
}

/* Open LMS patch for INT-19570 */
.block_report_graph .panel-footer,
.block_report_graph .report_graph .panel-footer {
    padding-top: 0;
}

.block_report_graph .chart-image {
    width: 100% !important; /* stylelint-disable-line declaration-no-important */
}

.drawer .block_report_graph .chart-image {
    height: 100% !important; /* stylelint-disable-line declaration-no-important */
}

.block_report_table .instantreportwait {
    display: block;
    position: absolute;
}

.block_report_table .rb-display-table-container {
    overflow: scroll;
    width: 100%;
}

.block_report_table .rb-loading .totara-table-container {
    opacity: 0.5;
}
.block_report_table .totara-toolbar-top {
    display: none;
}
.block_report_table #id_submitgroupstandard_clearstandardfilters {
    display: none;
}
.block_report_table #id_newfilterstandard {
    border: none;
}
.block_report_table .rb-display-table-container.loading {
    text-align: center;
}

.block_report_table .chart-image {
    width: 100% !important; /* stylelint-disable-line declaration-no-important */
}

.drawer .block_report_table .chart-image {
    height: 100% !important; /* stylelint-disable-line declaration-no-important */
}

#blocks-reports-view td.nothing {
    font-weight: bold;
    text-align: center;
}

#blocks-reports-view .highlightred {
    color: red;
}

#blocks-reports-view .iteratortable .cell {
    padding-top: 15px;
    padding-bottom: 15px;
}

#blocks-reports-view .iteratortable table .cell {
    padding: none;
}

#blocks-reports-view .exportbox {
    margin-top: 20px;
}

.path-blocks-reports .blockreportschart {
    text-align: center;
    margin-left:auto;
    margin-right:auto;
    margin-bottom: 20px;
    width: 100%;
    border: 1px solid gray;
}

/* Fix IE shadow text problem */
.path-blocks-reports .blockreportschart span {
    position: relative;
}

.path-blocks-reports .block-reports-hidden {display: none;}
#page-blocks-reports-view .mr_html_filter, #block-reports-filterbutton, .blocks_reports_useractions, .blocks_reports_jouleadmin {
    /* background-color: #F0EEEE; */
    background-color: #f5f7f7;

    border: 1px solid gray;

}
#page-blocks-reports-view .mr_html_filter{
    width: 100%;
    margin-bottom: 20px;
}


#block-reports-useraction-dragbox {
    background-color: #f4f6f6;
    border: 1px solid black;
}

.block-reports-box{
    width: 95%;
    padding: 5px;
}
.blocks_reports_useractions, .blocks_reports_jouleadmin {
    height: 90px;
    margin-bottom: 15px;
}

#page-blocks-reports-view .mr_html_table {
    overflow: auto;
}

#blocks-reports-cannedsqlurl {
    margin-bottom: 0.5em;
}

#blocks-reports-useraction-menu {
    float: right;
    margin: 15px;
}

#block-reports-useraction-msgtable textarea {
    height: 275px;
    width: 440px;
}

#block-reports-useraction-content .useraction-users {
    overflow: auto;
    height: 110px;
}

#block-reports-usernav {float: right;}

#block-reports-filterbutton {
    margin-bottom: 20px;
}

#block-reports-filterbutton input {margin: 10px;}

#block-reports-savequery-submit, #block-reports-savequery-name {float: left; margin: 15px;}
#block-reports-savequery-saved {float: right; margin: 15px;}
#block-reports-savequery-form label {float: left; margin: 15px 0px 0px 15px;}

#page-blocks-reports-view .mr_html_filter {clear: both;}
#page-blocks-reports-view .mr_html_filter fieldset {border: none; margin:0;}

.blocks_reports_tabs {clear: both;}
.blocks_reports_tabs a span {padding-right:10px;padding-top:10px;padding-bottom:3px;}

#block-reports-chart {
    height: 600px;
    width: 800px;
    text-align: center;
    margin-left: auto;
    margin-right: auto;
}

#page-blocks-reports-view span.bolded_text {
    font-weight: bolder;
}

.path-blocks-reports .course-report-dashboard {
    clear: right;
    display: block;
    width: 100%;
    height: 40px;
    overflow: hidden;
}

.path-blocks-reports .report-title {
    position: relative;
    float: left;
    font-size: 20px;
    font-weight: bold;
    height: 30px;
    margin-right: 20px;
    overflow: hidden;
    display: block;
}

.path-blocks-reports #course-title-row {
    width: 100%;
}

.path-blocks-reports .report-title#course-title span#course-title-text {
    width: 150px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    display: inline-block;
}

.path-blocks-reports .report-title#course-title a#course-overlay-toggle {
    white-space: nowrap;
    overflow: visible;
    display: inline-block;
    vertical-align: top;
}

.path-blocks-reports .yui3-js-enabled .yui3-overlay-loading {
    top:-1000em;
    left:-1000em;
    position:absolute;
    z-index: 4;
    display: none;
    visibility: hidden;
    hidden: 100%;
}

.path-blocks-reports .yui3-overlay-content .report-overlay-bd {
    padding:1px;
    background-color:#fff;
    overflow:visible;
}

.path-blocks-reports .report-nav-item {
    border-bottom-style: dotted;
    border-bottom-width: 1px;
    border-bottom-color: #d5d5d5;
    text-align: left;
    display: block;
    width: 98%;

}
.path-blocks-reports .report-nav-item-left{
    text-align: left;
    width: 49%;
    display: inline-block;
}

.path-blocks-reports .report-nav-item-right{
    text-align: right;
    width: 49%;
    display: inline-block;
}
.path-blocks-reports  .course-search-nav-item {
