@keyframes circleajax {
  0% {
    border-top-color: #646464;
    border-right-color: rgba(50, 50, 50, 0.25);
    border-bottom-color: rgba(50, 50, 50, 0.25);
    border-left-color: rgba(50, 50, 50, 0.25); }
  25% {
    border-top-color: rgba(50, 50, 50, 0.25);
    border-right-color: #646464;
    border-bottom-color: rgba(50, 50, 50, 0.25);
    border-left-color: rgba(50, 50, 50, 0.25); }
  50% {
    border-top-color: rgba(50, 50, 50, 0.25);
    border-right-color: rgba(50, 50, 50, 0.25);
    border-bottom-color: #646464;
    border-left-color: rgba(50, 50, 50, 0.25); }
  75% {
    border-top-color: rgba(50, 50, 50, 0.25);
    border-right-color: rgba(50, 50, 50, 0.25);
    border-bottom-color: rgba(50, 50, 50, 0.25);
    border-left-color: #646464; }
  100% {
    border-top-color: #646464;
    border-right-color: rgba(50, 50, 50, 0.25);
    border-bottom-color: rgba(50, 50, 50, 0.25);
    border-left-color: rgba(50, 50, 50, 0.25); } }

.block_snapfeeds .snap-media-object {
  font-weight: 500;
  padding: 0.5em 0; }
  .block_snapfeeds .snap-media-object::after {
    display: block;
    clear: both;
    content: ""; }
  .block_snapfeeds .snap-media-object > a:focus {
    display: block; }
  .block_snapfeeds .snap-media-object > a > img,
  .block_snapfeeds .snap-media-object > img {
    float: left;
    display: block;
    width: 36px;
    margin: .3em 1em 0 .3em;
    height: auto;
    vertical-align: baseline; }
  .block_snapfeeds .snap-media-object .snap-media-body {
    overflow: hidden; }
    .block_snapfeeds .snap-media-object .snap-media-body p,
    .block_snapfeeds .snap-media-object .snap-media-body small {
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
      margin: 0; }
