.block_snapfeeds .snap-sidebar-menu-more {
  display: block;
  text-align: right; }

.block_snapfeeds .snap-sidebar-menu-feed-loading:after {
  content: '';
  display: inline-block;
  position: relative;
  width: 20px;
  height: 20px;
  min-width: 20px;
  min-height: 20px;
  max-width: 20px;
  max-height: 20px;
  top: 0;
  left: 0;
  border: solid;
  border-width: 6px;
  border-radius: 50%;
  box-sizing: border-box;
  border-top-color: #323232;
  border-right-color: rgba(50, 50, 50, 0.25);
  border-bottom-color: rgba(50, 50, 50, 0.25);
  border-left-color: rgba(50, 50, 50, 0.25);
  animation-name: circleajax;
  animation-duration: 2s;
  animation-iteration-count: infinite;
  animation-timing-function: linear; }

