.noselect {
    -webkit-touch-callout: none; /* iOS Safari */
    -webkit-user-select: none; /* Safari */
    -khtml-user-select: none; /* Konqueror HTML */
    -moz-user-select: none; /* Old versions of Firefox */
    -ms-user-select: none; /* Internet Explorer/Edge */
    user-select: none; /* Non-prefixed version, currently
                                  supported by Chrome, Opera and Firefox */
}

/** SLIDER **/
label.switch {
    position: relative;
    display: inline-block;
    width: 40px;
    height: 22px;
    margin-bottom: 0;
}

.switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.intelliboard-slider {
    position: absolute;
    cursor: pointer;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: #ccc;
    -webkit-transition: .4s;
    transition: .4s;
}

.intelliboard-slider:before {
    position: absolute;
    content: "";
    height: 14px;
    width: 13px;
    left: 3px;
    bottom: 4px;
    background-color: white;
    -webkit-transition: .4s;
    -o-transition: .4s;
    transition: .4s;
}

input:checked + .intelliboard-slider {
    background-color: #2196F3;
}

input:focus + .intelliboard-slider {
    box-shadow: 0 0 1px #2196F3;
}

input:checked + .intelliboard-slider:before {
    -webkit-transform: translateX(20px);
    -ms-transform: translateX(20px);
    transform: translateX(20px);
}

.intelliboard-slider.round {
    border-radius: 12px;
}

.intelliboard-slider.round:before {
    border-radius: 50%;
}

/** SLIDER (END) **/

.choose-group .item {
    line-height: 18px;
    display: inline-block;
    padding: 7px 20px;
    border: 1px solid #e9ebf0;
    border-radius: 3px;
    margin-right: 10px;
    cursor: pointer;
    color: #646c73;
}

.choose-group .item.active {
    border-color: #2196F3;
}

.choose-group .item .round {
    position: relative;
    display: inline-block;
    margin-right: 5px;
}

.choose-group .item .round label {
    background-color: #fff;
    border: 1px solid #ccc;
    border-radius: 50%;
    cursor: pointer;
    height: 17px;
    left: 0;
    position: absolute;
    top: 0;
    width: 17px;
}

.choose-group .item .round label:after {
    border: 2px solid #fff;
    border-top: none;
    border-right: none;
    content: "";
    height: 6px;
    left: 3px;
    opacity: 0;
    position: absolute;
    top: 4px;
    transform: rotate(-45deg);
    width: 10px;
}

.choose-group .item .round input[type="checkbox"] {
    visibility: hidden;
}

.choose-group .item .round input[type="checkbox"]:checked + label {
    background-color: #2196F3;
    border-color: #2196F3;
}

.choose-group .item .round input[type="checkbox"]:checked + label:after {
    opacity: 1;
}

