/*override bootstrap form style*/
.path-local-intellicart select.form-control {
    padding: 0.375rem 0.75rem;
    background: #fff;
    max-width: 150px;
}
.path-local-intellicart .form-autocomplete-suggestions {
    top: 10px;
    left: 0;
}
/* layout styes */
.intellicart-content-box {
    border: 1px solid #ddd;
    padding: 1.25rem;
    border-radius: 0;
    box-shadow: 0 0 10px #ddd;
    background-color: #f7faff;
    overflow: hidden;
    color: #3c4145;
}
.intellicart-content-box .no-overflow {
    position: relative;
}
.intellicart-block-wrap {
    width: 100%;
}
.intellicart-content-box .pagination {
    margin-top: 0;
    justify-content: start !important;
}
.intellicart-content-box h2.title {
    font-size: 18px;
    color: #444;
    padding-bottom: 2rem;
    padding-top: 0.7rem;
    margin-bottom: 0;
}
.intellicart-content-box h2.title .intellicart-breadcrumbs {
    margin: 0;
    padding: 0;
    list-style: none;
}
.intellicart-content-box h2.title .intellicart-breadcrumbs li {
    display: inline-block;
    font-size: 1.2rem;
    margin-right: 0.5rem;
    position: relative;
    text-transform: capitalize;
}
.intellicart-content-box h2.title .intellicart-breadcrumbs li .br-divider {
    font-size: 1rem;
    padding-left: 1rem;
    opacity: 0.8;
}
.intellicart-content-box h2.title .intellicart-breadcrumbs li:last-child .br-divider {
    display: none;
}

.intellicart-content-box .widget-title {
    font-size: 1.3rem;
    color: #6b7076;
    margin-bottom: 1.3rem;
}
.intellicart-content-box .graph-container {
    height: 280px;
    overflow: hidden;
}
.intellicart-content-box .statistic li {
    float: left;
    border-right: 1px solid #e7e7e7;
    width: 16.6%;
    list-style: none;
    padding: 1.5rem 2rem;
    position: relative;
}
.intellicart-content-box .statistic li:last-child {
    border-right: 0;
}
.intellicart-content-box .statistic span.icon {
    position: absolute;
    left: 2rem;
    top: 1.5rem;
    font-size: 2.3rem;
    line-height: 2.5rem;
    color: #3da7d7;
}
.intellicart-content-box .statistic img.icon {
    height: 25px;
    width: auto;
    font-size: 3rem;
    max-width: 25px;
}
.intellicart-content-box .statistic .data {
    padding-left: 4rem;
}
.intellicart-content-box .statistic .numbers {
    white-space: nowrap;
    font-size: 2rem;
    line-height: 2rem;
    color: #2080cc;
}
.intellicart-content-box .statistic .numbers .cent,
.intellicart-content-box .statistic .numbers .sign {
    font-size: 1.5rem;
    display: inline-block;
    vertical-align: top;
    line-height: 1.4rem;
}
.intellicart-content-box .statistic .numbers span:not(first-of-type) {
    margin-left: -3px;
}
.intellicart-content-box .statistic .name {
    font-size: 1.2rem;
    line-height: 1.5rem;
    color: #414548;
    padding-top: 0.7rem;
    word-break: break-word;
}
.intellicart-content-box .shopping-cart-tablebox,
.intellicart-content-box .shopping-cart-formbox,
.intellicart-content-box .widget-content {
    border: 1px solid #ddd;
    border-radius: 4px;
    padding: 2rem;
    background-color: #fff;
    margin-bottom: 3rem;
}

.intellicart-content-box .seats-import table.generaltable {
    table-layout: fixed;
    word-break: break-all;
}
.seats-import .importseats_errors {
    color: #f00;
}
.seats-import .importseats_notify {
    color: #19a119;
}
.intellicart-content-box .shopping-cart-tablebox:hover,
.intellicart-content-box .shopping-cart-formbox:hover,
.intellicart-content-box .widget-content:hover {
    box-shadow: 0 0 1.2rem #eee;
}

.intellicart-content-box .graphs-widgets {
    overflow: hidden;
    margin: 0;
}
.intellicart-content-box .widget-item {
    width: 32.6%;
    float: left;
}
.intellicart-content-box .widget-item:nth-child(2n) {
    margin: 0 1%;
}

.intellicart-content-box .powered-by {
    text-align: right;
    padding-top: 1rem;
}

.intellicart-content-box .powered-by a {
    color: #999;
    text-decoration: underline;
}
.intellicart-content-box .powered-by a:hover {
    text-decoration: none;
}

/* tabs styes */
.intellicart-content-box:target {
    padding-top: 0 !important;
    margin-top: 0 !important;
}
.intellicart-content-box .intellicart-menu {
    margin: -1.25rem -1.25rem 1.25rem;
    background-color: #fff;
}
.intellicart-menu .nav-tabs {
    padding: 0 2rem !important;
    border-bottom: 1px solid #ddd;
    margin: 0 !important;
    background-color: transparent;
    border-radius: 0;
}
.intellicart-menu .nav-tabs .nav-item {
    margin: 0 0 -2px !important;
    padding: 0;
    float: left;
    display: block;
    background-color: transparent;
    border: 0;
    font-size: 1rem;
    border-radius: 0;
}
.intellicart-menu .nav-tabs .nav-link {
    display: block;
    background-color: transparent;
    padding: 1.2em 1.2em 1.2em 2.7em;
    border: 0;
    position: relative;
    border-bottom: 2px solid transparent;
    border-radius: 0;
    color: #9b9b9d;
    font-size: 1rem;
}
.intellicart-menu .nav-tabs .nav-link i {
    font-size: 22px;
    position: absolute;
    left: 0.5rem;
    top: 1.2rem;
}
.intellicart-menu .nav-tabs .nav-link:hover {
    border: 0;
    color: #327ebc;
    border-bottom: 2px solid #327ebc;
}
.intellicart-menu .nav-tabs .nav-link.active,
.intellicart-menu .nav-tabs .nav-link.active:hover {
    border: 0;
    border-bottom: 2px solid #327ebc;
    color: #327ebc;
    background-color: transparent;
}

/* inner-tabs styes */
.intellicart-content-box .inner-tabs {
    padding: 1rem 0 2rem;
}
.inner-tabs .nav-tabs {
    padding: 0 !important;
    border-bottom: 1px solid #ddd;
    margin: 0 !important;
    background-color: transparent;
    border-radius: 0;
}
.inner-tabs .nav-tabs .nav-item {
    margin: 0 0 -2px !important;
    padding: 0;
    float: left;
    display: block;
    background-color: transparent;
    border: 0;
    font-size: 1rem;
    border-radius: 0;
}
.inner-tabs .nav-tabs .nav-link {
    display: block;
    background-color: transparent;
    padding: 0.5rem 3rem;
    border: 0;
    position: relative;
    border-bottom: 2px solid transparent;
    border-radius: 0;
    color: #9b9b9d;
    font-size: 1rem;
}
.inner-tabs .nav-tabs .nav-link:focus,
.inner-tabs .nav-tabs .nav-link:hover {
    border: 0;
    color: #327ebc;
    border-bottom: 2px solid #327ebc;
}
.inner-tabs .nav-tabs .nav-link.active,
.inner-tabs .nav-tabs .nav-link.active:focus,
.inner-tabs .nav-tabs .nav-link.active:hover {
    border: 0;
    border-bottom: 2px solid #327ebc;
    color: #327ebc;
    background-color: transparent;
}

/* tables */
.intellicart-content-box table.generaltable thead th {
    font-size: 12px;
    text-transform: uppercase;
    font-weight: 500;
    color: #999;
    text-shadow: 0 0 1px #e7e7e7;
    padding: 0.5rem 0.75rem 1.2rem;
    border: 0;
}
.intellicart-content-box table.generaltable thead th a {
    font-size: 12px;
    text-transform: uppercase;
    font-weight: 500;
    color: #888;
    text-shadow: 0 0 1px #e7e7e7;
}
.intellicart-content-box table.generaltable tbody td {
    padding: 0.75rem;
    font-size: 1rem;
    border-top: 1px solid #e7e7e7;
}
.intellicart-content-box table.generaltable a.action-icon .icon {
    color: #9198a8;
    font-size: 1rem;
}
.intellicart-content-box table.generaltable a.action-icon.disabled .icon,
.intellicart-content-box
table.generaltable
a.action-icon.disabled.active
.icon {
    color: #ccc;
}
.intellicart-content-box table.generaltable a.action-icon.active .icon,
.intellicart-content-box table.generaltable a.action-icon .icon:hover {
    color: #3c4145;
}
.intellicart-content-box table.generaltable a:first-of-type > .icon,
.intellicart-content-box table.generaltable span:first-of-type > .icon {
    margin-left: 0;
}

#page-local-intellicart-catsubscriptions-index .c0,
.intellicart-categories-index .shopping-cart-tablebox .c0 {
    display: none;
}
.intellicart-categories-index
.shopping-cart-tablebox
.intellicart-bulk-actions-table
.c0 {
    display: table-cell;
}
.intellicart-categories-index
.shopping-cart-tablebox
.intellicart-bulk-actions-table
.c1 {
