.overlay {
    display: none;
    align-items: center;
    justify-content: center;
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    background: rgba(0, 0, 0, 0.8);
    z-index: 10000;
}

.overlay .spinner {
    display: flex;
    justify-content: center;
    align-items: center;
}

.overlay .spinner::after {
    content: "";
    width: 50px;
    height: 50px;
    border: 2px solid #ccc;
    border-top: 2px solid #aaa;
    border-radius: 100%;
    will-change: transform;
    animation: overlayspinner 2s infinite linear;
}

@keyframes overlayspinner {
    from {
        transform: rotate(0deg);
    }
    to {
        transform: rotate(360deg);
    }
}

