.intellidata-support-bg {
    width: 300px;
    height: 410px;
    background-size: 360px auto !important;
    position: absolute;
    bottom: 0;
    left: 0;
    z-index: 0;
}

.intellidata-support-player button {
    margin-top: 10px;
    position: absolute;
}

.intellidata-support-player {
    top: 5%;
    left: calc(50% - 500px);
    width: 1000px;
    z-index: 9999;
    display: none;
    text-align: center;
    box-shadow: 0 50px 50px 50px rgba(0, 0, 0, 0.6);
    position: absolute;
}

.intellidata-support-play:hover {
    opacity: 0.8;
}

.intellidata-support-play {
    width: 200px;
    height: 200px;
    background-size: 200px 200px !important;
    position: absolute;
    right: 3%;
    bottom: 3%;
    z-index: 0;
    cursor: pointer;
}

.intellidata-support {
    height: 550px;
    background-size: auto 550px !important;
    border: 1px solid #ddd;
    position: relative;
    padding: 50px 30px;
    box-sizing: border-box;
}

.intellidata-support-text {
    max-width: 60%;
    color: #333;
    margin-bottom: 40px;
    z-index: 1;
    position: relative;
    line-height: 21px;
    text-align: center;
    font-weight: 500;
}

.intellidata-support-text h2 {
    font-size: 1.2rem;
    color: #333;
}

.intellidata-support-version a {
    font-weight: 700;
}

.intellidata-proceed-setup {
    font-size: 16px;
    font-weight: 700;
    padding: 15px 0 25px;
}

.intellidata-support-terms {
    text-align: left;
    font-size: 13px;
    line-height: 1.53;
    color: #a2aac1;
    letter-spacing: .3px;
    z-index: 1;
    position: relative;
    width: calc(100% - 400px);
    margin: 25px;
}

.intellidata-support-links-header {
    font-size: 15px;
    color: #444d66;
    font-weight: 500;
    margin: 40px auto 30px;
    max-width: 90%;
    position: relative;
    text-align: left;
}

.intellidata-support-contacts {
    margin: 25px;
    z-index: 1;
    position: relative;
    width: calc(100% - 400px);
}

.intellidata-support-contacts a {
    margin-left: 0;
}

.intellidata-support-contacts strong {
    display: block;
    font-size: 12px;
    color: #545e7b;
    letter-spacing: .3px;
    font-weight: 500;
}

.intellidata-footer-contact {
    font-size: 13px;
}

.intellidata-support-version {
    padding: 0 0 15px;
    font-size: 16px;
}

.intellidata-proposals {
    display: flex;
    margin: 20px 0;
}

.intellidata-proposal {
    flex: 0 0 33.333333%;
    padding: 0 20px;
    line-height: 24px;
    font-size: 15px;
}

.intellidata-proposal .proposal-title {
    font-weight: 700;
}

@media screen and (max-width: 1400px) {
    .intellidata-support-links-header,
    .intellidata-proposal {
        font-size: 14px;
        line-height: 20px;
    }
}

@media screen and (max-width: 1200px) {

    body .intellidata-support div {
        width: 100%;
        max-width: 100%;
    }

    body .intellidata-support-player button {
        display: none;
    }

    body .intellidata-support-player {
        display: block;
        position: relative;
        top: 0;
        left: 0;
        width: 100%;
        box-shadow: none;
    }

    body .intellidata-support-play {
        display: none;
    }

    body .intellidata-support {
        height: auto;
        background: #f7fafe !important;
    }
}

@media screen and (max-width: 800px) {
    .intellidata-proposals {
        display: block;
    }
    .intellidata-proposal {
        padding: 0 10px 20px;
    }
}

@media screen and (min-width: 2500px) {
    .intellidata-support-text {
        max-width: 70%;
    }
}

