/* Container für das Bild */
#unilabel-imageboard-preview .image-container {
    position: relative;
    display: inline-block;
    cursor: move;
}

/* Bild-Stil */
#unilabel-imageboard-preview .image-container img {
    display: block;
}

/* Der Punkt: Diagonal geteiltes Quadrat */
#unilabel-imageboard-preview .dot {
    position: absolute;
    top: 0; /* Abstand vom oberen Rand */
    left: 0; /* Abstand vom linken Rand */
    width: 20px; /* Breite des Quadrats */
    height: 20px; /* Höhe des Quadrats */
    pointer-events: none; /* Interaktionslos */
    opacity: 0; /* Unsichtbar im Normalzustand */
    transition: opacity 0.3s ease; /* Weicher Übergang beim Hover */
}

/* Oberes Dreieck */
#unilabel-imageboard-preview .dot::before {
    content: '';
    position: absolute;
    width: 0;
    height: 0;
    border-style: solid;
    border-width: 0 20px 20px 0; /* Diagonales Dreieck */
    border-color: transparent #333 #eee transparent; /* Obere Dreieckfarbe (schwarz) */
    top: 0;
    left: 0;
}

/* Hover-Effekt */
#unilabel-imageboard-preview .image-container:hover .dot {
    opacity: 1; /* Quadrat wird sichtbar */
}

