/*Bookmarks page*/

/*Bookmarks page course, category and sort block*/
.path-local-learningtools-ltool-bookmarks .top-block {
    text-align: right;
    margin-bottom: 20px;
}
.path-local-learningtools-ltool-bookmarks .top-block .course-block,
.path-local-learningtools-ltool-bookmarks .top-block #ltnote-coursefilter {
    float: left;
    margin-bottom: 20px;
    margin-right: 15px;
}
.path-local-learningtools-ltool-bookmarks .top-block .ltnote-activityfilter,
.path-local-learningtools-ltool-bookmarks .top-block .ltnote-activityfilter {
    display: inline-block;
    float: left;
    margin-bottom: 15px;
}
.path-local-learningtools-ltool-bookmarks .top-block > div:last-child {
    display: inline-block;
}
.path-local-learningtools-ltool-bookmarks .top-block > div select {
    min-width: 250px;
    width: auto;
    text-align: left;
    border: 1px solid #ccc;
    border-radius: 5px;
    background: none;
    padding: 5px;
    display: inline-block;
}
.path-local-learningtools-ltool-bookmarks .top-block > div select:after {
    float: right;
    margin-top: 10px;
}

/*Sort block*/
.path-local-learningtools-ltool-bookmarks .top-block > div.sort-block {
    margin-bottom: 20px;
}
.path-local-learningtools-ltool-bookmarks .top-block > div.sort-block select {
    display: inline-block;
}
.path-local-learningtools-ltool-bookmarks .top-block > div.sort-block select:focus,
.path-local-learningtools-ltool-bookmarks .top-block > div.sort-block select:active,
.path-local-learningtools-ltool-bookmarks .top-block > div.sort-block select:focus:active {
    outline: none;
    box-shadow: none;
}

/*Course listing block*/
.bookmarks-list-info .activity-block .course-element {
    clear: both;
    margin-top: 20px;
}
.bookmarks-list-info .activity-block .course-element .course-list {
    display: flex;
    margin-bottom: 15px;
    background: #fff;
    padding: 15px;
    border: 2px solid #ccc;
    align-items: center;
}
.bookmarks-list-info .activity-block .course-element .course-list > div {
    width: 100%;
    margin-right: 5px;
    display: flex;
    align-items: center;
}
.bookmarks-list-info .activity-block .course-element .course-list > div p {
    font-size: 16px;
    font-weight: 600;
    margin-bottom: 0;
}
.bookmarks-list-info .activity-block .course-element .course-list > div i {
    font-size: 16px;
    line-height: 24px;
    margin-right: 30px;
    vertical-align: middle;
}
.bookmarks-list-info .activity-block .course-element .course-list .category-item p {
    font-size: 16px;
    font-weight: 600;
    color: #999;
}
.bookmarks-list-info .activity-block .course-element .course-list .right-block {
    margin-left: 30px;
    justify-content: end;
}
.bookmarks-list-info .activity-block .course-element .course-list .right-block .calendar-block {
    margin-right: 30px;
}
.bookmarks-list-info .activity-block .course-element .course-list .right-block .calendar-block p {
    font-size: 13px;
    font-weight: normal;
    color: #999;
}
.bookmarks-list-info .activity-block .course-element .course-list .right-block .delete-block a {
    color: #000;
    background: none;
    box-shadow: none;
    margin-right: 15px;
    display: inline-flex;
}
.bookmarks-list-info .activity-block .course-element .course-list .right-block .delete-block a i {
    font-size: 13px;
    margin-right: 0;
}
.bookmarks-list-info .activity-block .course-element .course-list .right-block .button-block button {
    min-width: 100px;
    height: auto;
    color: #fff;
    font-size: 13px;
    font-weight: 500;
    text-decoration: none;
    padding: 4px 10px;
    background: #000;
    display: inline-block;
}

@media (min-width: 501px) and (max-width: 767px) {
    .bookmarks-list-info .activity-block .course-element .course-list > div.category-item {
        width: 60%;
    }
}

@media (max-width: 500px) {

    .bookmarks-list-info .activity-block .course-element .course-list {
        display: block;
    }
    .bookmarks-list-info .activity-block .course-element .course-list > div {
        display: block;
        margin-bottom: 10px;
    }
    .bookmarks-list-info .activity-block .course-element .course-list > div p {
        width: 85%;
        display: inline-block;
        vertical-align: middle;
    }
    .bookmarks-list-info .activity-block .course-element .course-list > div i {
        margin-right: 10px;
    }
    .bookmarks-list-info .activity-block .course-element .course-list > div.category-item {
        width: 100%;
        margin-left: 27px;
    }
    .bookmarks-list-info .activity-block .course-element .course-list .right-block {
        text-align: right;
        margin-left: 0;
        margin-right: 15px;
    }
    .bookmarks-list-info .activity-block .course-element .course-list .right-block .calendar-block {
        text-align: left;
        margin-bottom: 10px;
        margin-left: 27px;
    }
    .bookmarks-list-info .activity-block .course-element .course-list .right-block .calendar-block p {
        width: 100%;
    }
    .bookmarks-list-info .activity-block .course-element .course-list .right-block .delete-block {
        display: inline-block;
    }
    .bookmarks-list-info .activity-block .course-element .course-list .right-block .button-block {
        display: inline-block;
    }
}

@media (max-width: 400px) {
    .bookmarks-list-info .activity-block .course-element .course-list .right-block .calendar-block {
        float: none;
        margin-right: 0;
        display: block;
    }
}


/*floating button*/
.local-learningtools .floating-button div.ltbookmarksinfo button {
    background: #343a40;
}
.local-learningtools .floating-button div.ltbookmarksinfo button:hover p {
    background: #343a40;
}
.local-learningtools .floating-button div.ltbookmarksinfo button i + span {
    display: none;
}
.local-learningtools .floating-button div.ltbookmarksinfo button i.marked + span {
    width: 18px;
    height: 18px;
    line-height: 18px;
    font-size: 10px;
    box-shadow: 2px 3px 5px rgba(0, 0, 0, 0.3);
    border-radius: 50%;
    background: #2e9f7f;
    display: block;
    right: -7px;
}

body.local-learningtools #page-wrapper #disable-focusmode {
    position: fixed;
    z-index: 6;
    text-align: right;
    right: 60px;
    top: 35px;
}

body.local-learningtools div#disable-focusmode .btn.btn-primary {
    border-radius: 22px;
    box-shadow: 2px 5px 5px rgb(0 0 0 / 20%);
}
/*Notes page*/

/*Notes page course, category and sort block*/
.path-local-learningtools-ltool-note .top-block {
    text-align: right;
    margin-bottom: 20px;
}

.path-local-learningtools-ltool-note .top-block .course-block,
.path-local-learningtools-ltool-note .top-block #ltnote-coursefilter {
    float: left;
    margin-bottom: 20px;
    margin-right: 15px;
}

.path-local-learningtools-ltool-note .top-block #ltnote-coursefilter,
.path-local-learningtools-ltool-note .top-block .ltnote-activityfilter {
    display: inline-block;
    float: left;
    margin-bottom: 15px;
}

.path-local-learningtools-ltool-note .top-block > div:last-child {
    display: inline-block;
}

.path-local-learningtools-ltool-note .top-block > div.ltbookmarks-coursefilter {
    text-align: left;
    float: none;
    display: block;
}

.path-local-learningtools-ltool-note .top-block > div.ltnote-sortfilter {
    margin-left: 20px;
    margin-bottom: 20px;
}

.path-local-learningtools-ltool-note .top-block > div.ltnote-sortfilter i {
    margin-right: 5px;
}

.path-local-learningtools-ltool-note .top-block > div select {
    min-width: 250px;
    width: auto;
    text-align: left;
    border: 1px solid #ccc;
    border-radius: 5px;
    background: none;
    padding: 5px;
    display: inline-block;
}

.path-local-learningtools-ltool-note .top-block > div select:after {
    float: right;
    margin-top: 10px;
}

/*sort block*/
.path-local-learningtools-ltool-note .top-block > div.sort-block {
    margin-bottom: 20px;
}

.path-local-learningtools-ltool-note .top-block > div.sort-block select {
    border: 0;
    display: inline-block;
}

.path-local-learningtools-ltool-note .top-block > div.sort-block select:focus,
.path-local-learningtools-ltool-note .top-block > div.sort-block select:active,
.path-local-learningtools-ltool-note .top-block > div.sort-block select:focus:active {
    outline: none;
    box-shadow: none;
}

/*Notes main body - Accordion block*/
.ltnotes-mainbody {
    margin-top: 20px;
    clear: both;
}

.ltnotes-mainbody .card {
    border: 0;
    padding-top: 10px;
    margin-bottom: 20px;
}

.ltnotes-mainbody .card + .card {
    border-top: 1px solid #ccc;
}

/*Accordion header content*/
.ltnotes-mainbody .card .card-header {
    padding: 0;
    margin-bottom: 20px;
    border: 0;
    background: none;
}

.ltnotes-mainbody .card .card-header h5 button {
    width: 100%;
    color: #000;
    font-size: 20px;
    text-align: left;
    text-decoration: none;
    display: block;
}

.ltnotes-mainbody .card .card-header h5 button:after {
    content: '\f103';
    font-family: var(--fa-style-family, "Font Awesome 6 Free", "Font Awesome 6 Brands", fontawesome);
    font-weight: 700;
    float: right;
}

.ltnotes-mainbody .card .card-header h5 button.collapsed:after {
    content: '\f102';
    font-family: var(--fa-style-family, "Font Awesome 6 Free", "Font Awesome 6 Brands", fontawesome);
    font-weight: 700;
}

/*Accordion body content*/
.ltnotes-mainbody .card .card-body {
    border: 1px solid #eee;
    margin-bottom: 20px;
}

.ltnotes-mainbody .card .card-body .content-block .title-block {
    text-align: right;
}

.ltnotes-mainbody .card .card-body .content-block .title-block h4 {
    font-size: 15px;
    font-weight: bold;
    margin-top: 5px;
    float: left;
    margin-right: 15px;
}

.ltnotes-mainbody .card .card-body .content-block .title-block .details-block {
    display: inline-block;
}

.ltnotes-mainbody .card .card-body .content-block .title-block .details-block .calendar-block {
    margin-right: 10px;
}

.ltnotes-mainbody .card .card-body .content-block .title-block .details-block .btn-block {
    width: auto;
    display: inline-block;
}

@media (max-width: 575px) {
    .ltnotes-mainbody .card .card-body .content-block .title-block h4 {
        text-align: left;
        float: none;
    }

    .ltnotes-mainbody .card .card-body .content-block .title-block .details-block {
        display: block;
    }

    .ltnotes-mainbody .card .card-body .content-block .title-block .details-block .calendar-block {
        float: left;
    }
}

/*Modal popup css*/
.learningtool-note .modal .modal-dialog .modal-header h5.modal-title {
    width: 100%;
}

.learningtool-note .modal .modal-dialog .modal-header h5.modal-title .popout-block {
    float: right;
    display: flex;
}

.learningtool-note .modal .modal-dialog .modal-header h5.modal-title .popout-block #popout-action {
    font-size: 13px;
    color: #000;
    margin-right: 5px;
    display: inline-block;
    vertical-align: middle;
    border: 0;
    background: none;
}

.learningtool-note .modal .modal-dialog .modal-header h5.modal-title .popout-block i {
    font-size: 13px;
    line-height: 24px;
    color: #000;
    display: inline-block;
}

.learningtool-note .modal .modal-body .ltoolusernotes {
    width: 100%;
}

.learningtool-note .modal .modal-body .ltoolusernotes form .editor_atto .editor_atto_content_wrap .editor_atto_content,
.learningtool-note .modal .modal-body .ltoolusernotes form .editor_atto .editor_atto + textarea {
    border: 1px solid #ccc;
}

.learningtool-note .modal .modal-body .list-context-existnotes {
    margin-top: 20px;
}

.learningtool-note .modal .modal-body .list-context-existnotes h3 {
    margin-bottom: 20px;
}

.learningtool-note .modal .modal-body .list-context-existnotes .usernotes-mainbody .card {
    margin-bottom: 5px;
    border: 1px solid #ccc;
}

.learningtool-note .modal .modal-body .list-context-existnotes .usernotes-mainbody .card .card-header {
    padding: 0;
    border-bottom: 0;
    background: #efefef;
}

.learningtool-note .modal .modal-body .list-context-existnotes .usernotes-mainbody .card .card-header h5 button {
    width: 100%;
    color: #000;
    font-weight: bold;
    text-align: left;
    text-decoration: none;
}

.learningtool-note .modal .modal-body .list-context-existnotes .usernotes-mainbody .card .card-header h5 button:after {
    content: '\f102';
    font-family: var(--fa-style-family, "Font Awesome 6 Free", "Font Awesome 6 Brands", fontawesome);
    font-weight: 700;
    float: right;
}

.learningtool-note .modal .modal-body .list-context-existnotes .usernotes-mainbody .card .card-header h5 button.collapsed:after {
    content: '\f103';
}

.learningtool-note .modal .modal-body .list-context-existnotes .usernotes-mainbody .card .collapse .card-body,
.learningtool-note .modal .modal-body .list-context-existnotes .usernotes-mainbody .card .collapsing .card-body {
    padding: 10px;
    border-bottom: 1px solid #efefef;
}

.learningtool-note .modal .modal-body .list-context-existnotes .usernotes-mainbody .card .collapse .card-body:last-child,
.learningtool-note .modal .modal-body .list-context-existnotes .usernotes-mainbody .card .collapsing .card-body:last-child {
    border-bottom: 0;
}

.learningtool-note .modal .modal-body .list-context-existnotes .usernotes-mainbody .card .collapse .content-block .title-block,
.learningtool-note .modal .modal-body .list-context-existnotes .usernotes-mainbody .card .collapsing .content-block .title-block {
    float: right;
}

.learningtool-note .modal .modal-body .list-context-existnotes .usernotes-mainbody .card .collapse .content-block .action-block,
.learningtool-note .modal .modal-body .list-context-existnotes .usernotes-mainbody .card .collapsing .content-block .action-block {
    text-align: right;
    margin-left: 10px;
}

.learningtool-note .modal .modal-body .usernotes-mainbody .card .collapse .content-block .action-block .edit-action,
.learningtool-note .modal .modal-body .usernotes-mainbody .card .collapsing .content-block .action-block .edit-action {
    display: inline-block;
}

.learningtool-note .modal .modal-body .usernotes-mainbody .card .collapse .content-block .action-block .delete-action,
.learningtool-note .modal .modal-body .usernotes-mainbody .card .collapsing .content-block .action-block .delete-action {
    display: inline-block;
}

.learningtool-note .modal .modal-body .list-context-existnotes .usernotes-mainbody .card .collapse .content-block .desc-block,
.learningtool-note .modal .modal-body .list-context-existnotes .usernotes-mainbody .card .collapsing .content-block .desc-block {
    margin-top: 15px;
}

.learningtool-note .modal .modal-body .usernotes-mainbody .card .collapse .content-block .desc-block p:empty,
.learningtool-note .modal .modal-body .usernotes-mainbody .card .collapsing .content-block .desc-block p:empty {
    display: none;
}


/*floating button*/
.local-learningtools .floating-button div.ltnoteinfo button {
    background: #17a2b8;
}

.local-learningtools .floating-button div.ltnoteinfo button span {
    display: none;
}

.local-learningtools .floating-button div.ltnoteinfo button span.ticked {
    display: block;
}

.local-learningtools .floating-button div.ltnoteinfo button:hover p {
    background: #17a2b8;
}

#page-local-learningtools-ltool-note-editlist .mform .form-group {
    margin-right: 1rem;
}

#page-local-learningtools-ltool-note-editlist .mform .femptylabel .col-form-label {
    flex: 0;
}

#page-local-learningtools-ltool-note-editlist .mform .felement {
    flex: 0 0 100%;
    max-width: 100%;
}

#page-local-learningtools-ltool-note-editlist .mform {
    margin-top: 2rem;
}

.ltool-note-popout #page-content .activity-header {
    display: none;
}

/* Print page styles */
.ltool-note-print-page {
    padding: 20px;
    line-height: 1.6;
}

.ltool-note-print-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 30px;
    padding-bottom: 20px;
    border-bottom: 2px solid #e9ecef;
}

.ltool-note-print-title {
    font-size: 28px;
    font-weight: 600;
    margin: 0;
}

.ltool-note-print-actions {
    display: flex;
    gap: 12px;
}

.ltool-note-print-btn {
    font-size: 14px;
    font-weight: 500;
    border: none;
    border-radius: 6px;
    padding: 10px 20px;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 8px;
    transition: all 0.2s ease;
}

.ltool-note-print-btn-primary {
    color: white;
    background: #007bff;
}

.ltool-note-print-btn-primary:hover {
    background: #0056b3;
    transform: translateY(-1px);
}

.ltool-note-print-btn-secondary {
    color: white;
    background: #6c757d;
}

.ltool-note-print-btn-secondary:hover {
    background: #545b62;
    transform: translateY(-1px);
}

.ltool-notes-container .ltool-notes-grid .note-card {
    margin-bottom: 30px;
    display: flex;
    gap: 30px;
    justify-content: space-between;
}

.ltool-notes-container .ltool-notes-grid .note-card .note-content {
    width: 100%;
    border-right: 1px solid #ccc;
    padding-right: 20px;
}

.ltool-notes-container .ltool-notes-grid .note-card .note-footer {
    width: 100%;
}

.ltool-notes-container .ltool-notes-grid .note-card .note-footer .note-title-block {
    display: flex;
    justify-content: space-between;
    /* flex-wrap: wrap; */
}

.ltool-notes-container .ltool-notes-grid .note-card .note-footer .note-title-block .note-title {
    width: 100%;
}

.ltool-notes-container .ltool-notes-grid .note-card .note-footer .note-title-block .note-actions button {
    width: 30px;
    height: 30px;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background: #f5f5f5;
}

.ltool-notes-container .ltool-notes-grid .note-card .note-footer .note-title-block .note-actions button i.icon {
    margin-right: 0;
}

.ltool-notes-container .ltool-notes-grid .note-card .note-footer .note-timestamp {
    margin-top: 10px;
}

@media (min-width: 1400px) {
    .ltool-notes-container .ltool-notes-grid .note-card .note-footer {
        max-width: 400px;
    }
}

@media (max-width: 1399px) {
    .ltool-notes-container .ltool-notes-grid .note-card .note-footer {
        max-width: 300px;
    }
}

@media (max-width: 1199px) {
    .ltool-notes-container .ltool-notes-grid .note-card .note-footer {
        max-width: 120px;
    }
}

@media (max-width: 991px) {
    .ltool-notes-container .ltool-notes-grid .note-card .note-footer {
        max-width: 200px;
    }
}

@media (max-width: 575px) {
    .ltool-notes-container .ltool-notes-grid .note-card .note-footer {
        max-width: 150px;
    }
}

/* Simple print styles - back to basics */
@media print {
    .ltool-note-print-actions,
    .ltool-note-print-btn,
    .ltool-no-print {
        display: none;
    }
}

/* Loading state */
.ltool-note-print-loading {
    color: #6c757d;
    text-align: center;
    padding: 40px;
}

.ltool-note-print-loading i {
    font-size: 24px;
    margin-bottom: 10px;
}

#ltoolschedule-editorbox form #fgroup_id_buttonar {
    display: none;
}
.questionattemptiframewrapper {
    width: 100%;
    overflow: hidden;
}

